const listActiveTenants = `-- name: ListActiveTenants :many
select id, timezone from tenants where status in ('trial', 'active')
`

type ListActiveTenantsRow struct {
	ID       uuid.UUID `json:"id"`
	Timezone string    `json:"timezone"`
}

// tenants carries no RLS policy (see modules/school/repository.go), so
// this is safe to run off the pool directly for the platform-wide expiry
// and token-cleanup jobs, which must iterate every tenant.
func (q *Queries) ListActiveTenants(ctx context.Context) ([]ListActiveTenantsRow, error) {
	rows, err := q.db.Query(ctx, listActiveTenants)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListActiveTenantsRow{}
	for rows.Next() {
		var i ListActiveTenantsRow
		if err := rows.Scan(&i.ID, &i.Timezone); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

